  const refDate = died ? died : new Date(2025, 6, 1);
  let age = refDate.getFullYear() - birthday.getFullYear();
  const monthDiff = refDate.getMonth() - birthday.getMonth();
  if (monthDiff < 0 || (monthDiff === 0 && refDate.getDate() < birthday.getDate())) {
