	age := asOf.Year() - birthday.Year()
	anniversary := time.Date(asOf.Year(), birthday.Month(), birthday.Day(), 0, 0, 0, 0, birthday.Location())
	if asOf.Before(anniversary) {
		age--
	}
	return age
}

